//! Separate station-first Radio app; no podcast feeds, credentials or stream URL fields.
use crate::{*,serde_json::{json,Value}};
const FAVORITES:&str="radio_favorites";const PREFS:&str="radio_preferences";
const GENRES:&[(&str,&str)]=&[("","All"),("pop","Pop"),("rock","Rock"),("jazz","Jazz"),("classical","Classical"),("dance","Dance"),("ambient","Relax"),("country","Country"),("blues","Blues"),("soul","Soul"),("80s","80s"),("90s","90s"),("latin","Latin"),("world","World")];
fn summary(r:&Value)->Value{json!({"id":r["id"],"name":r["name"],"countrycode":r["countrycode"],"codec":r["codec"],"aliases":r["aliases"]})}
fn selected(s:&Value,id:&str)->Option<Value>{s["results"].as_array().into_iter().flatten().chain(s["favorites"].as_array().into_iter().flatten()).chain(s["recent"].as_array().into_iter().flatten()).chain(std::iter::once(&s["current"])).find(|r|r["id"]==id).map(summary)}
fn same(a:&Value,b:&Value)->bool{a["id"].is_string()&&(a["id"]==b["id"]||a["aliases"].as_array().into_iter().flatten().any(|id|id==&b["id"])||b["aliases"].as_array().into_iter().flatten().any(|id|id==&a["id"]))}
fn favorite_target(s:&Value,row:Value)->Value{s["favorites"].as_array().into_iter().flatten().find(|r|same(r,&row)).cloned().unwrap_or(row)}
fn saved(s:&Value,id:&str)->bool{let row=selected(s,id).unwrap_or(json!({"id":id}));s["favorites"].as_array().into_iter().flatten().any(|r|same(r,&row))||(same(&s["current"],&row)&&s["current_favorite"]==true)}

fn filters(s:&Value)->Value{json!([s["query"],s["genre"],s["country"],s["language"]])}
fn search(s:&mut Value,offset:u64)->Value{s["tab"]=json!("explore");s["pending_offset"]=json!(offset);s["pending_filters"]=filters(s);s["pending_search_label"]=json!(if s["query"].as_str().unwrap_or("").trim().is_empty(){s["genre"].as_str().unwrap_or("")}else{s["query"].as_str().unwrap_or("")});s["failure_visible"]=json!(false);s["status"]=json!("Finding compatible public stations…");radio::search(json!({"query":s["query"],"tag":if !s["query"].as_str().unwrap_or("").trim().is_empty()&&s["genre"]=="music"{json!("")}else{s["genre"].clone()},"country":s["country"],"language":s["language"],"offset":offset,"auto_hide":s["auto_hide"]!=false,"show_unavailable":s["show_unavailable"]==true}),"radio.found")}
fn prefs(s:&Value,then:&str)->Value{collections::transact(PREFS,s["prefs_revision"].as_u64().unwrap_or(0),1,None,vec![collections::put("prefs",json!({"recent":s["recent"],"genre":s["genre"],"country":s["country"],"language":s["language"],"auto_hide":s["auto_hide"]!=false,"show_unavailable":s["show_unavailable"]==true}))],then)}
pub fn controller(input:Value)->Value{let mut s=input["state"].clone();if !s.is_object(){s=json!({"tab":"explore","status":"","query":"","genre":"","country":"","language":"","results":[],"favorites":[],"recent":[],"current":null,"current_favorite":false,"prefs_revision":0,"favorites_revision":0,"favorites_next":null,"next":null,"offset":0});}
if !s["auto_hide"].is_boolean(){s["auto_hide"]=json!(true);}if !s["show_unavailable"].is_boolean(){s["show_unavailable"]=json!(false);}
let e=&input["event"];let a=e["action"].as_str().unwrap_or("");let ok=e["reply"]["ok"]==true;let v=&e["reply"]["value"];let mut req=Value::Null;
match a{
"start"=>{s["initial_browse"]=json!(false);s["status"]=json!("Choose a category or search for a station.");req=collections::get(PREFS,"prefs","radio.prefs.loaded");},
"radio.prefs.loaded" if ok=>{s["prefs_revision"]=v["revision"].clone();if let Some(data)=v.get("item").and_then(|r|r.get("data")).or_else(||v.get("data")){for key in["genre","country","language"]{if data[key].is_string(){s[key]=data[key].clone()}}for key in ["auto_hide","show_unavailable"]{if data[key].is_boolean(){s[key]=data[key].clone();}}s["recent"]=json!(data["recent"].as_array().into_iter().flatten().take(40).cloned().collect::<Vec<_>>());s["current"]=s["recent"].as_array().and_then(|r|r.first()).cloned().unwrap_or(Value::Null);}if s["genre"]=="music"{s["genre"]=json!("");}req=collections::page(FAVORITES,"",None,"radio.favorites.loaded");},
"radio.favorites.loaded" if ok=>{s["favorites_revision"]=v["revision"].clone();s["favorites"]=json!(v["items"].as_array().into_iter().flatten().map(|r|r["data"].clone()).collect::<Vec<_>>());s["favorites_next"]=v["next"].clone();s["current_favorite"]=json!(s["favorites"].as_array().into_iter().flatten().any(|r|same(r,&s["current"])));if s["initial_browse"]==true{s["initial_browse"]=json!(false);req=search(&mut s,0);}},
"radio.favorites.first"=>req=collections::page(FAVORITES,"",None,"radio.favorites.loaded"),
"radio.favorites.more"=>req=collections::page(FAVORITES,s["favorites_next"].as_str().unwrap_or(""),s["favorites_revision"].as_u64(),"radio.favorites.loaded"),
"radio.settings"=>s["settings"]=json!(true),"radio.settings.close"=>s["settings"]=json!(false),"radio.filters.reset"=>{s["genre"]=json!("");s["country"]=json!("");s["language"]=json!("");s["query"]=json!("");s["settings"]=json!(false);req=search(&mut s,0);},"radio.close"=>s["close"]=json!(true),
"radio.listen"=>s["tab"]=json!("listen"),"radio.explore"=>s["tab"]=json!("explore"),"radio.library"=>{s["tab"]=json!("favorites");req=collections::page(FAVORITES,"",None,"radio.favorites.loaded");},
"radio.query"=>s["query"]=e["value"].clone(),"radio.country"=>s["country"]=json!(e["value"].as_str().unwrap_or("").to_ascii_uppercase()),"radio.language"=>s["language"]=e["value"].clone(),
"radio.genre"=>{s["genre"]=e["value"].clone();s["query"]=json!("");req=search(&mut s,0);},
"radio.auto.hide"|"radio.show.hidden"=>{s[if a=="radio.auto.hide"{"auto_hide"}else{"show_unavailable"}]=json!(e["value"].as_str()==Some("true"));req=search(&mut s,0);},"radio.hide.failed"|"radio.hide.current"=>{let row=if s["failed_station"].is_object(){s["failed_station"].clone()}else{s["current"].clone()};if row["id"].is_string(){s["settings"]=json!(false);let id=row["id"].clone();s["failed_station"]=Value::Null;s["just_hidden"]=json!(true);req=search(&mut s,0);req["args"]["hide_station"]=id;}},"radio.retry.hidden"=>{s["settings"]=json!(false);req=search(&mut s,0);req["args"]["retry_unavailable"]=json!(true);},"radio.refresh"=>{s["settings"]=json!(false);req=search(&mut s,0);req["args"]["refresh"]=json!(true);},"radio.search"=>req=search(&mut s,0),"radio.next"=>{if let Some(n)=s["next"].as_u64(){req=search(&mut s,n)}},"radio.previous"=>{let off=s["offset"].as_u64().unwrap_or(0).saturating_sub(20);req=search(&mut s,off)},
"radio.found" if ok=>{s["offset"]=s["pending_offset"].clone();s["search_filters"]=s["pending_filters"].clone();s["search_label"]=s["pending_search_label"].clone();s["results"]=v["items"].clone();s["next"]=v["next"].clone();s["status"]=json!(if s["results"].as_array().is_none_or(Vec::is_empty){"No stations found. Try another search or filter."}else{""});if s["just_hidden"]==true{s["just_hidden"]=json!(false);s["status"]=json!("Station hidden for 24 hours. Show it again in Radio settings.");}req=prefs(&s,"radio.prefs.saved");},
_ if a.starts_with("radio.play.")=>{let id=&a[11..];if let Some(row)=selected(&s,id){s["pending_station"]=row;s["status"]=json!("Connecting to your selected station…");req=radio::station_play(id,"radio.played");}},
"radio.failure.close"=>{s["failure_visible"]=json!(false);s["status"]=json!("");},"radio.retry"|"radio.retry.failed"=>{let row=if (a=="radio.retry.failed"||!s["current"].is_object())&&s["failed_station"].is_object(){s["failed_station"].clone()}else{s["current"].clone()};s["failure_visible"]=json!(false);if let Some(id)=row["id"].as_str(){s["pending_station"]=row.clone();req=radio::station_play(id,"radio.played");}},
"radio.played" if ok=>{let row=summary(&v["station"]);s["failed_station"]=Value::Null;s["failure_visible"]=json!(false);s["current"]=row.clone();let mut recent=vec![row.clone()];recent.extend(s["recent"].as_array().into_iter().flatten().filter(|r|r["id"]!=row["id"]).take(39).cloned());s["recent"]=json!(recent);s["status"]=json!("");req=collections::get(FAVORITES,favorite_target(&s,row.clone())["id"].as_str().unwrap_or(""),"radio.favorite.checked");},
"radio.favorite.checked" if ok=>{s["favorites_revision"]=v["revision"].clone();s["current_favorite"]=json!(v["data"].is_object());req=prefs(&s,"radio.prefs.saved");},
"radio.prefs.saved" if ok=>s["prefs_revision"]=v["revision"].clone(),
"radio.favorite"=>{if s["current"].is_object(){s["favorite_target"]=favorite_target(&s,s["current"].clone());let id=s["favorite_target"]["id"].as_str().unwrap_or("").to_string();req=collections::get(FAVORITES,&id,"radio.favorite.before");}},
_ if a.starts_with("radio.star.")=>{if let Some(row)=selected(&s,&a[11..]){let row=favorite_target(&s,row);let id=row["id"].as_str().unwrap_or("").to_string();s["favorite_target"]=row;req=collections::get(FAVORITES,&id,"radio.favorite.before");}},
"radio.favorite.before" if ok=>{let id=s["favorite_target"]["id"].as_str().unwrap_or("").to_string();let exists=v["data"].is_object();s["favorite_removing"]=json!(exists);req=collections::transact(FAVORITES,v["revision"].as_u64().unwrap_or(0),1,None,vec![if exists{collections::delete(&id)}else{collections::put(&id,s["favorite_target"].clone())}],"radio.favorite.saved");},
"radio.favorite.saved" if ok=>{if same(&s["current"],&s["favorite_target"]){s["current_favorite"]=json!(s["favorite_removing"]!=true)}s["status"]=json!("");req=collections::page(FAVORITES,"",None,"radio.favorites.loaded");},
"radio.clear.recent"=>{s["confirm_clear"]=json!(true)},"radio.clear.cancel"=>s["confirm_clear"]=json!(false),"radio.clear.accept"=>{s["confirm_clear"]=json!(false);s["recent"]=json!([]);req=prefs(&s,"radio.prefs.saved");},_=>{}}
if e["reply"]["ok"]==false{if a=="radio.played"{s["failure_visible"]=json!(true);s["failed_station"]=s["pending_station"].clone();}s["status"]=json!(if a=="radio.prefs.saved"{"Preferences could not be saved. Reopen Radio to reload; favorites and playback are kept."}else if a=="radio.favorite.saved"{"Your favorite change was not saved. Reload favorites and try again; existing data was kept."}else if a=="radio.played"{e["reply"]["error"].as_str().unwrap_or("Could not connect. Retry or choose another station.")}else{"Radio is unavailable or permission is off. Your favorites are kept. Allow Radio stations in Settings > Apps, then try again."});}
let mut body=Vec::new();
for(action,label,tab)in[("radio.explore","Stations","explore"),("radio.listen","Recent","listen"),("radio.library","Favorites","favorites")]{let mut n=button(action,label).row("radio.tabs");n["tab"]=json!(true);n["selected"]=json!(s["tab"]==tab);body.push(n);}
match s["tab"].as_str().unwrap_or("explore"){
"listen"=>{rows(&mut body,&s["recent"],&s);if s["recent"].as_array().is_none_or(Vec::is_empty){body.push(label("radio.recent.empty","No recent stations"));}else{let mut n=button("radio.clear.recent","Clear recent stations");n["subtle"]=json!(true);body.push(n);}},
"favorites"=>{body.push(heading("radio.favorites.title","Your Favorite stations"));rows(&mut body,&s["favorites"],&s);if s["favorites_next"].is_string(){body.push(button("radio.favorites.more","More favorites"));}},
_=>{body.push(field("radio.query","Search stations",s["query"].as_str().unwrap_or("")).limit(80));
body.push(filter("select","radio.country","Country",s["country"].as_str().unwrap_or(""),&[("","Anywhere"),("US","United States"),("GB","United Kingdom"),("CA","Canada"),("AU","Australia"),("DE","Germany"),("FR","France"),("ES","Spain"),("IT","Italy"),("BR","Brazil"),("MX","Mexico"),("IN","India"),("JP","Japan"),("ZA","South Africa"),("NG","Nigeria"),("SE","Sweden"),("NL","Netherlands"),("NZ","New Zealand"),("AR","Argentina"),("IE","Ireland")]));body.push(filter("select","radio.language","Language",s["language"].as_str().unwrap_or(""),&[("","Any language"),("english","English"),("spanish","Spanish"),("french","French"),("german","German"),("portuguese","Portuguese"),("arabic","Arabic"),("hindi","Hindi"),("russian","Russian"),("italian","Italian"),("japanese","Japanese"),("chinese","Chinese"),("korean","Korean"),("swedish","Swedish"),("greek","Greek"),("dutch","Dutch"),("polish","Polish")]));body.push(choices("chips","radio.genre","Genre",s["genre"].as_str().unwrap_or(""),GENRES));body.push(primary_button("radio.search","Find stations"));rows(&mut body,&s["results"],&s);if s["offset"].as_u64().unwrap_or(0)>0{body.push(button("radio.previous","Previous stations").enabled(s["search_filters"]==filters(&s)));}if s["next"].is_number(){body.push(button("radio.next","More stations").enabled(s["search_filters"]==filters(&s)));}}}
if s["failure_visible"]!=true&&s["status"].as_str().is_some_and(|v|!v.is_empty()){body.push(label("radio.status",s["status"].as_str().unwrap()));}
let mut player=media::player("radio.player");player["radio"]=json!(true);player["dock"]=json!(true);
if s["current"].is_object(){player["title"]=s["current"]["name"].clone();player["retry"]=json!("radio.retry");player["long_action"]=json!("radio.favorite");player["favorite"]=json!(s["current_favorite"]==true);player["favorite_label"]=json!(if s["current_favorite"]==true{"Remove favorite"}else{"Add favorite"});}
body.push(player);let clear=s["confirm_clear"]==true;let settings=s["settings"]==true;let close=s["close"]==true;let tab=s["tab"].as_str().unwrap_or("explore").to_string();
let failure_visible=s["failure_visible"]==true;let failure_title=s["failed_station"]["name"].as_str().unwrap_or("Could not connect").to_string();let failure_text=s["status"].as_str().unwrap_or("Retry or choose another station.").to_string();let screen_has_selection=s["current"]["id"].is_string()||s["failed_station"]["id"].is_string();let auto_hide=s["auto_hide"]!=false;let show_unavailable=s["show_unavailable"]==true;let mut screen=Screen::new("Radio",s).body(body).actions(vec![icon("radio.settings","Radio settings","settings")]).scroll_key(&format!("radio.{tab}")).scrollable().effect(req);
if settings{let mut menu=vec![heading("radio.visibility.title","Station visibility"),toggle("radio.auto.hide","Auto-hide failed stations",auto_hide),label("radio.visibility.help","Busy or timed-out stations stay visible."),toggle("radio.show.hidden","Show hidden stations",show_unavailable),button("radio.retry.hidden","Unhide all stations")];if screen_has_selection{menu.push(button("radio.hide.current","Hide selected station"));}menu.extend(vec![heading("radio.source.title","Station directories"),label("radio.source","Radio Browser + Icecast"),button("radio.refresh","Refresh stations"),button("radio.filters.reset","Reset station filters"),button("radio.settings.close","Done")]);screen=screen.dialog("Radio settings","radio.settings.close",menu);}

else if failure_visible{screen=screen.dialog(&failure_title,"radio.failure.close",vec![label("radio.failure.message",&failure_text),primary_button("radio.retry.failed","Retry station"),button("radio.hide.failed","Hide for now").row("radio.failure"),button("radio.failure.close","Close").row("radio.failure")]);}
if clear{screen=screen.confirm_labeled("Clear recent stations?","Your favorites and current playback will be kept.","radio.clear.accept","radio.clear.cancel","Clear");}if close{screen=screen.close();}screen.finish()}
fn filter(kind:&str,id:&str,text:&str,value:&str,options:&[(&str,&str)])->Value{let mut n=choices(kind,id,text,value,options);n["compact"]=json!(true);n}

fn rows(body:&mut Vec<Value>,rows:&Value,s:&Value){for row in rows.as_array().into_iter().flatten().take(40){if let(Some(id),Some(name))=(row["id"].as_str(),row["name"].as_str()){let detail=[row["countrycode"].as_str().unwrap_or(""),row["codec"].as_str().unwrap_or("Live radio")].into_iter().filter(|v|!v.is_empty()).collect::<Vec<_>>().join(" · ");let mut n=record(&format!("radio.play.{id}"),name,&detail).trailing(&format!("radio.star.{id}"),if saved(s,id){"Remove favorite"}else{"Add favorite"},if saved(s,id){"bookmark.filled"}else{"bookmark"});n["radio_station"]=json!(id);n["hide_unavailable"]=json!(s["tab"]=="explore");body.push(n);}}}
#[cfg(test)]mod tests{use super::*;
#[test]fn polished_tabs_recent_and_settings_keep_the_page_focused(){let f=controller(json!({}));assert_eq!(f["state"]["tab"],"explore");let tabs:Vec<_>=f["body"].as_array().unwrap().iter().filter(|n|n["tab"]==true).map(|n|n["text"].as_str().unwrap()).collect();assert_eq!(tabs,vec!["Stations","Recent","Favorites"]);let f=controller(json!({"state":f["state"],"event":{"action":"radio.listen"}}));assert!(!f["body"].to_string().contains("radio.genre"));assert!(!f["body"].to_string().contains("Find your sound"));let menu=controller(json!({"state":f["state"],"event":{"action":"radio.settings"}}));assert_eq!(menu["menu_title"],"Radio settings");}
#[test]fn saved_stations_have_filled_bookmarks_and_independent_play_actions(){let mut s=controller(json!({}))["state"].clone();let id="aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa";s["tab"]=json!("listen");s["recent"]=json!([{"id":id,"name":"Music"}]);s["favorites"]=s["recent"].clone();let f=controller(json!({"state":s}));let row=f["body"].as_array().unwrap().iter().find(|n|n["kind"]=="record").unwrap();assert_eq!(row["id"],format!("radio.play.{id}"));assert_eq!(row["trailing"]["id"],format!("radio.star.{id}"));assert_eq!(row["trailing"]["icon"],"bookmark.filled");assert!(f["body"].as_array().unwrap().iter().any(|n|n["id"]=="radio.clear.recent"&&n["subtle"]==true));}
#[test]fn compact_filters_keep_selected_values_inside_the_controls(){let f=controller(json!({}));for id in ["radio.country","radio.language"]{let n=f["body"].as_array().unwrap().iter().find(|n|n["id"]==id).unwrap();assert_eq!(n["compact"],true);assert!(n.get("row").is_none());}let f=controller(json!({"state":f["state"],"event":{"action":"radio.library"}}));assert!(!f["body"].to_string().contains("First favorites"));assert!(!f["body"].to_string().contains("Save stations using"));}
#[test]fn last_station_is_restored_without_autoplay(){let station=json!({"id":"aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa","name":"Last Jazz"});let f=controller(json!({"event":{"action":"radio.prefs.loaded","reply":{"ok":true,"value":{"revision":2,"data":{"recent":[station]}}}}}));assert_eq!(f["state"]["current"]["name"],"Last Jazz");assert_eq!(f["effect"]["service"],"collections.query");let player=f["body"].as_array().unwrap().iter().find(|n|n["id"]=="radio.player").unwrap();assert_eq!(player["title"],"Last Jazz");assert_eq!(player["retry"],"radio.retry");}
#[test]fn radio_starts_local_separately_and_has_no_credential_or_url_fields(){let f=controller(json!({"event":{"action":"start"}}));assert_eq!(f["effect"]["args"]["name"],PREFS);assert!(f["body"].as_array().unwrap().iter().any(|r|r["id"]=="radio.player"&&r["dock"]==true));assert!(!f["body"].to_string().contains("Podcast"));}
#[test]fn radio_search_is_bounded_and_station_selection_never_passes_a_url(){let f=controller(json!({"event":{"action":"radio.search"}}));assert_eq!(f["effect"]["service"],"radio.search");assert_eq!(f["effect"]["args"]["offset"],0);let mut s=f["state"].clone();let id="aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa";s["results"]=json!([{"id":id,"name":"Music","countrycode":"US","codec":"MP3"}]);let p=controller(json!({"state":s,"event":{"action":format!("radio.play.{id}")}}));assert_eq!(p["effect"]["service"],"radio.play");assert_eq!(p["effect"]["args"],json!({"station":id}));}
#[test]fn radio_favorites_get_live_revision_before_changing_and_failures_keep_data(){let mut s=controller(json!({}))["state"].clone();let id="aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa";s["favorites"]=json!([{"id":id,"name":"Saved"}]);let f=controller(json!({"state":s,"event":{"action":format!("radio.star.{id}")}}));assert_eq!(f["effect"]["service"],"collections.get");let f=controller(json!({"state":f["state"],"event":{"action":"radio.favorite.before","reply":{"ok":true,"value":{"revision":17,"data":{"name":"Saved"}}}}}));assert_eq!(f["effect"]["args"]["expected_revision"],17);assert_eq!(f["effect"]["args"]["operations"][0]["operation"],"delete");let f=controller(json!({"state":f["state"],"event":{"action":"radio.favorite.saved","reply":{"ok":false}}}));assert_eq!(f["state"]["favorites"].as_array().unwrap().len(),1);}
#[test]fn opening_keeps_browsing_idle_and_directory_aliases_preserve_old_bookmarks(){let f=controller(json!({"event":{"action":"start"}}));let f=controller(json!({"state":f["state"],"event":{"action":"radio.prefs.loaded","reply":{"ok":true,"value":{"revision":0,"data":{"genre":"music"}}}}}));let f=controller(json!({"state":f["state"],"event":{"action":"radio.favorites.loaded","reply":{"ok":true,"value":{"revision":0,"items":[]}}}}));assert!(f["effect"].is_null());assert_eq!(f["state"]["genre"],"");let mut s=f["state"].clone();s["results"]=json!([{"id":"new","name":"Jazz","aliases":["old"]}]);s["favorites"]=json!([{"id":"old","name":"Jazz"}]);let f=controller(json!({"state":s}));assert!(f["body"].as_array().unwrap().iter().any(|r|r["trailing"]["icon"]=="bookmark.filled"));let f=controller(json!({"state":f["state"],"event":{"action":"radio.star.new"}}));assert_eq!(f["effect"]["args"]["id"],"old");}

#[test]fn failure_actions_retry_the_attempted_station_and_keep_the_error_specific(){let mut s=controller(json!({}))["state"].clone();s["current"]=json!({"id":"old","name":"Previous"});s["pending_station"]=json!({"id":"failed","name":"Selected"});let f=controller(json!({"state":s,"event":{"action":"radio.played","reply":{"ok":false,"error":"The station server is busy. Try again shortly."}}}));assert!(f["state"]["status"].as_str().unwrap().contains("busy"));let retry=controller(json!({"state":f["state"],"event":{"action":"radio.retry.failed"}}));assert_eq!(retry["effect"]["args"]["station"],"failed");let hide=controller(json!({"state":retry["state"],"event":{"action":"radio.hide.failed"}}));assert_eq!(hide["effect"]["args"]["hide_station"],"failed");}
#[test]fn visibility_controls_are_explicit_and_travel_with_search_and_saved_preferences(){let f=controller(json!({"event":{"action":"radio.settings"}}));for id in ["radio.auto.hide","radio.show.hidden","radio.retry.hidden","radio.settings.close"]{assert!(f["menu"].as_array().unwrap().iter().any(|n|n["id"]==id));}let f=controller(json!({"state":f["state"],"event":{"action":"radio.auto.hide","value":"false"}}));assert_eq!(f["effect"]["args"]["auto_hide"],false);let f=controller(json!({"state":f["state"],"event":{"action":"radio.show.hidden","value":"true"}}));assert_eq!(f["effect"]["args"]["show_unavailable"],true);}

}
